import React from 'react';
import { useAuth } from '../context/AuthContext';
import { IconShieldFilled, IconLock, IconGlobe } from '../Icons';

const Footer = () => {
  const { darkMode } = useAuth();

  return (
    <footer style={{
      background: darkMode ? '#1E293B' : '#1E3A5F',
      padding: '24px 32px',
      marginTop: 'auto'
    }}>
      <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <IconShieldFilled size={20} />
          <span style={{ color: '#0EA5E9', fontWeight: 800, fontSize: '16px' }}>KibaliGuard</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <IconLock color="#10B981" size={14} />
            <span style={{ color: '#94A3B8', fontSize: '12px', fontWeight: 500 }}>Kenya Data Protection Act 2019 Compliant</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <IconGlobe color="#0EA5E9" size={14} />
            <span style={{ color: '#0EA5E9', fontWeight: 700, fontSize: '13px' }}>© Cheryl Kreativ Studio</span>
          </div>
        </div>
        <div style={{ color: '#64748B', fontSize: '12px', textAlign: 'center', width: '100%' }}>
          Your data. Your rules. Your control.
        </div>
      </div>
    </footer>
  );
};

export default Footer;
